def sha256_file(path: Path) -> str:
    return sha256(path.read_bytes()).hexdigest()


def verify_contract(path: Path) -> None:
    if not path.is_file():
        raise FileNotFoundError(f"Actual OII-004 module missing: {path}")
    source = path.read_text(encoding="utf-8")
    required = (
        'ENGINE_ID = "OII-004"',
        "class SourceDependencyIndependencePackage",
        "class EvidenceIndependenceAssessment",
        "def verify_independence_package",
        "source_independence_score",
        "dependent_evidence_node_ids",
        "shared_primary_origin_node_ids",
        "shared_origin_group_ids",
        "circular_dependency_penalty",
        "probability_estimation_allowed",
    )
    missing = [token for token in required if token not in source]
    if missing:
        raise RuntimeError(
            "Actual OII-004 contract mismatch; missing: "
            + ", ".join(missing)
        )
    print("[OK] Actual OII-004 dependency/independence contract verified")


def write_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source.lstrip(), encoding="utf-8", newline="\n")
    ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    print(f"[OK] FULL REPLACEMENT: {path.resolve()}")


def append_export(path: Path, line: str) -> None:
    existing = path.read_text(encoding="utf-8") if path.exists() else ""
    if line in existing.splitlines():
        print(f"[OK] PACKAGE EXPORT PRESENT: {path.resolve()}")
        return
    if existing and not existing.endswith("\n"):
        existing += "\n"
    path.write_text(existing + line + "\n", encoding="utf-8", newline="\n")
    ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    print(f"[OK] PACKAGE UPDATED: {path.resolve()}")


def main() -> int:
    print("========================================")
    print(" OII-005 INSTALLER")
    print(" REDUNDANCY / NOVELTY ENGINE")
    print("========================================")

    if not (ROOT / "qseries_v2").is_dir():
        raise SystemExit(
            "[ERROR] Run this installer from the kalshi-qss-bot repository root."
        )

    verify_contract(SOURCE_OII004)
    protected_hash = sha256_file(SOURCE_OII004)

    write_replacement(PRODUCTION, PRODUCTION_SOURCE)
    write_replacement(TEST, TEST_SOURCE)
    append_export(
        PACKAGE_INIT,
        "from .oracle_redundancy_novelty_engine import *",
    )

    if sha256_file(SOURCE_OII004) != protected_hash:
        raise RuntimeError("Protected OII-004 module changed during installation")
    print("[PASS] Protected OII-004 module unchanged")

    completed = subprocess.run(
        [sys.executable, str(TEST)],
        cwd=str(ROOT),
        check=False,
    )
    if completed.returncode:
        raise SystemExit(completed.returncode)

    if sha256_file(SOURCE_OII004) != protected_hash:
        raise RuntimeError("Protected OII-004 module changed during testing")

    print("[PASS] Protected OII-004 module unchanged after test")
    print("[PASS] No acquisition, Operator, or Q Series package modified")
    print("[OK] OII-005 test executed automatically")
    print("[DONE] OII-005 REDUNDANCY / NOVELTY INSTALLED")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
